package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class UnifiedRecordsDialog {
 static void show(MainActivity owner){LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(20,12,20,12);EditText query=new EditText(owner);query.setHint("会話・要約・読み取り・保留を検索");query.setSingleLine(true);query.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(160)});box.addView(query);Spinner type=new Spinner(owner);String[] types={"","conversation","meeting","reading","inbox","memo","continuation"};type.setAdapter(new ArrayAdapter<String>(owner,android.R.layout.simple_spinner_dropdown_item,new String[]{"すべて","会話","会議","読み取り","保留案件","メモ","会話の続き"}));box.addView(type);EditText from=new EditText(owner),until=new EditText(owner);from.setHint("開始日 YYYY-MM-DD（任意）");until.setHint("終了日 YYYY-MM-DD（任意）");from.setSingleLine(true);until.setSingleLine(true);box.addView(from);box.addView(until);CheckBox pending=new CheckBox(owner);pending.setText("保留中の案件だけ");box.addView(pending);Button search=new Button(owner);search.setText("端末内の記録を検索");box.addView(search);TextView status=new TextView(owner);box.addView(status);LinearLayout rows=new LinearLayout(owner);rows.setOrientation(1);box.addView(rows);Button readings=new Button(owner);readings.setText("読み取り・訂正履歴を開く");readings.setOnClickListener(v->ReadingHistoryDialog.list(owner));box.addView(readings);ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("記録の横断検索").setView(scroll).setPositiveButton("閉じる",null).create();search.setOnClickListener(v->{String q=query.getText().toString(),selected=types[type.getSelectedItemPosition()],first=from.getText().toString().trim(),last=until.getText().toString().trim();boolean onlyPending=pending.isChecked();search.setEnabled(false);new Thread(()->{try{JSONObject data=UnifiedRecords.search(owner,q,new JSONObject().put("type",selected).put("from",first.isEmpty()?0:java.time.LocalDate.parse(first).atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli()).put("until",last.isEmpty()?Long.MAX_VALUE:java.time.LocalDate.parse(last).plusDays(1).atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli()-1).put("pending",onlyPending));owner.runOnUiThread(()->{if(!dialog.isShowing())return;status.setText(data.optString("scope")+"\n一致 "+data.optInt("matched")+"件 / 対象 "+("会話 "+data.optJSONObject("counts").optInt("conversation")+" / 会議 "+data.optJSONObject("counts").optInt("meeting")+" / 読み取り "+data.optJSONObject("counts").optInt("reading")+" / 保留 "+data.optJSONObject("counts").optInt("inbox"))+"\n未取得・制限："+data.optJSONArray("issues"));rows.removeAllViews();JSONArray results=data.optJSONArray("items");for(int i=0;results!=null&&i<results.length();i++){JSONObject item=results.optJSONObject(i);Button b=new Button(owner);b.setText(kind(item.optString("type"))+" / "+new java.util.Date(item.optLong("at"))+"\n"+item.optString("title"));b.setOnClickListener(a->open(owner,item));rows.addView(b);}});}catch(Exception e){owner.runOnUiThread(()->status.setText("検索できません。検索語と保存状態を確認してください"));}finally{owner.runOnUiThread(()->search.setEnabled(true));}},"UnifiedRecordSearch").start();});dialog.show();}
 static void open(MainActivity owner,JSONObject row){String type=row.optString("type"),id=row.optString("id");if(row.optJSONObject("answer")!=null){AnswerCorrectionDialog.show(owner,row.optJSONObject("answer"));return;}if(type.equals("reading")){ReadingHistoryDialog.show(owner,id);return;}if(type.equals("inbox")){new SecretaryInboxDialog(owner).open(id);return;}if(type.equals("meeting")){MeetingReviewDialog.show(owner,id);return;}new AlertDialog.Builder(owner).setTitle(kind(type)+" / "+new java.util.Date(row.optLong("at"))).setMessage(row.optString("body")).setPositiveButton("閉じる",null).show();}
 static String kind(String type){return type.equals("memo")?"メモ":type.equals("continuation")?"会話の続き":type.equals("conversation")?"会話":type.equals("meeting")?"会議":type.equals("reading")?"画像の読み取り":"保留案件";}
 private UnifiedRecordsDialog(){}
}
